from pathlib import Path
import json,csv,hashlib,copy,sys
ROOT=Path(__file__).resolve().parents[6]
P=Path(__file__).resolve().parent
M=json.loads((P/'MEMBER_CONTEXT.json').read_text());D=M['dossier'];PK=P.parent.parent
rationale='EO 8083 independently extends retirement coverage, replaces Rule II section 3(d), and supersedes EO 3375, all effective May 1, 1939. Complete official page 1577 and EO 9830 Parts I–III were read; images of original page 1 and actor pages 1,4,5,11 were inspected. EO 9830 names 8083 without exception in Part III, under the opening global effective date May 1, 1947. January 24, 1942 statutory coverage revision and EO 9154 exclusions are earlier functional replacement candidates, disclosed under the owner ruling on unnamed instruments, not earlier formal ends of this named order. Wartime recruitment and 1946 transitional rules do not erase all earlier status rights. Historical supersession, completed appointments and accrued retirement or status rights are distinguished from continuing commands of revoked 8083.'
earlier='No own sunset or completion duty appears in the full original. Eligibility conditions are not termination triggers. Read the January 24, 1942 Act section 3 and EO 9154 sections 1–3 as earlier retirement regime changes; neither names 8083, so the owner unnamed-instruments rule retains the later named end while disclosing both candidates. Read EO 9063 and 9691: special war-service appointment status and later resumption do not expressly revoke 8083. No earlier named ending located in the bounded OFR/local/web searches. EO 9830 global effective date is May 1, 1947, rather than signing February 24.'
scope='Corrected three disjoint spans cover the preamble and all original commands: retirement extension; Rule II section 3(d) replacement, removal exception and commission recommendation; supersession of 3375 and express commencement. The alleged uncovered section 631 is an authority citation. EO 9830 Part III revokes 8083 by number without a limiting proviso, with successor rules in Part II.'
independent='Retirement coverage and appointment/transfer eligibility are independent provisions, both covered by named whole-order revocation. Recommendation of issuance is not a reporting command. Supersession of 3375 took legal effect May 1, 1939 and is a completed change of law; ending 8083 does not reverse that historical effect or revive 3375. No duty to establish a board, transfer property or complete a report remains.'
savings='Accrued retirement and competitive status rights, completed appointments and the completed supersession are distinguished from continuing 8083 authority. EO 9154 section 3 explicitly protects retirement rights acquired before its May 1, 1942 issuance despite January 24 retroactivity; the 1942 Act section 10 preserves rights of persons separated before its effective date. EO 9691 section 9 saves acquired reemployment rights. EO 9830 Part II recognizes competitive status and provides successor authority, but has no general clause continuing 8083 as an order. No individual pension payment or current right is inferred.'
rat={'8083_main':rationale,'8083_earlier':earlier,'8083_scope':scope,'8083_independent':independent,'8083_savings':savings}
(P/'RATIONALES.json').write_text(json.dumps(rat,indent=2)+'\n')
with (PK/'decisions.csv').open() as f:rd=csv.DictReader(f);fields=rd.fieldnames;row=next(x for x in rd if x['instrument_id']=='EO:8083')
row.update(outcome='submit',approved='true',original_confirmed='true',original_pages_confirmed='true',inventory_confirmed='true',research_rationale='@rationale:8083_main',savings_state='transferred_or_accrued',savings_source_id='ORIGINAL:EO:8083',savings_reason='@rationale:8083_savings',search_ids=json.dumps(['later-events:ofr_catalog','current-law:usc','current-law:ecfr']),unresolved_material_gaps='[]',earlier_end_check='@rationale:8083_earlier',scope_check='@rationale:8083_scope',independent_command_check='@rationale:8083_independent',savings_check='@rationale:8083_savings',working_text='{}')
with (P/'decisions.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerow(row)
with (PK/'clauses.csv').open() as f:rd=csv.DictReader(f);fields=rd.fieldnames;base=next(x for x in rd if x['instrument_id']=='EO:8083')
scopes=[('retirement-extension',794,1791,'Retirement coverage is an independent legal extension; broader 1942 statutory coverage and exclusions are disclosed earlier functional changes, not a named 8083 ending under the owner rule. Personal accrued rights are separately preserved.'),('rule-ii-3d',1791,2458,'The replacement appointment and status rule, including denial of removal protection, remains amended until parent ending under the owner strike-and-insert ruling. EO 9830 replaces the rules and expressly revokes 8083 and 7915 on its global effective date.'),('supersession-and-effective-date',2458,2692,'The supersession of 3375 is a legal change effective May 1, 1939, not an unperformed future task. Formal revocation ends 8083 authority without reviving 3375 or undoing historical effects; May 1, 1939 is commencement, not expiration.')]
rows=[]
for suffix,a,b,reason in scopes:
 c=base.copy();c.update(scope_id='EO:8083#'+suffix,clause_id='',state='terminated',end_id='ACT:EO:8083>EO:9830',effective_date='1947-05-01',effective_date_confirmed='true',reason=reason,inventory_source_id='ORIGINAL:EO:8083',inventory_char_start=str(a),inventory_char_end=str(b),inventory_reason='Complete original page inspection corrects truncated machine inventory; disjoint spans include all independent operative provisions and authority citation 631.');rows.append(c)
with (P/'clauses.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
print('csv exports written')
